# ------------------------------------------------------------
# SCHEMA DUMP FOR TABLE: v_sat_alertas_criticas
# ------------------------------------------------------------

CREATE OR REPLACE VIEW `v_sat_alertas_criticas` AS
select
  `sa`.`id_alerta_sat` AS `id_alerta_sat`,
  `f`.`id_tenant` AS `id_tenant`,
  `f`.`nombre` AS `finca`,
  `l`.`codigo` AS `lote`,
  `sa`.`fecha_deteccion` AS `fecha_deteccion`,
  `sa`.`tipo_anomalia` AS `tipo_anomalia`,
  `sa`.`descripcion` AS `descripcion`,
  `sa`.`nivel_severidad` AS `nivel_severidad`
from
  (
  (
    (
    `sat_alertas_anomalias` `sa`
    join `lotes` `l` on((`l`.`id_lote` = `sa`.`id_lote`))
    )
    join `nucleos` `n` on((`n`.`id_nucleo` = `l`.`id_nucleo`))
  )
  join `fincas` `f` on((`f`.`id_finca` = `n`.`id_finca`))
  )
where
  (
  (`sa`.`nivel_severidad` in ('Alta', 'Critica'))
  and (`sa`.`estado` = 'Activa')
  );

# ------------------------------------------------------------
# SCHEMA DUMP FOR TABLE: v_sat_dashboard
# ------------------------------------------------------------

CREATE OR REPLACE VIEW `v_sat_dashboard` AS
select
  `t`.`id_tenant` AS `id_tenant`,(
  select
    count(0)
  from
    (
    (
      (
      `sat_imagenes` `si`
      join `lotes` `l` on((`l`.`id_lote` = `si`.`id_lote`))
      )
      join `nucleos` `n` on((`n`.`id_nucleo` = `l`.`id_nucleo`))
    )
    join `fincas` `f` on((`f`.`id_finca` = `n`.`id_finca`))
    )
  where
    (`f`.`id_tenant` = `t`.`id_tenant`)
  ) AS `total_imagenes_descargadas`,(
  select
    count(0)
  from
    (
    (
      (
      `sat_alertas_anomalias` `sa`
      join `lotes` `l` on((`l`.`id_lote` = `sa`.`id_lote`))
      )
      join `nucleos` `n` on((`n`.`id_nucleo` = `l`.`id_nucleo`))
    )
    join `fincas` `f` on((`f`.`id_finca` = `n`.`id_finca`))
    )
  where
    (
    (`f`.`id_tenant` = `t`.`id_tenant`)
    and (`sa`.`estado` = 'Activa')
    )
  ) AS `alertas_activas`,(
  select
    count(0)
  from
    (
    `sat_vuelos_drones` `sv`
    join `fincas` `f` on((`f`.`id_finca` = `sv`.`id_finca`))
    )
  where
    (
    (`f`.`id_tenant` = `t`.`id_tenant`)
    and (`sv`.`estado` = 'Planificado')
    )
  ) AS `vuelos_drones_pendientes`
from
  `tenants` `t`;

# ------------------------------------------------------------
# SCHEMA DUMP FOR TABLE: v_sat_ndvi_historial_lote
# ------------------------------------------------------------

CREATE OR REPLACE VIEW `v_sat_ndvi_historial_lote` AS
select
  `l`.`id_lote` AS `id_lote`,
  `l`.`codigo` AS `codigo_lote`,
  `si`.`fecha_captura` AS `fecha_captura`,
  `si`.`fuente` AS `satelite`,
  `sli`.`valor_promedio` AS `ndvi_valor`,
  `sli`.`clasificacion` AS `estado_salud`
from
  (
  (
    (
    `lotes` `l`
    join `sat_imagenes` `si` on((`si`.`id_lote` = `l`.`id_lote`))
    )
    join `sat_lecturas_indices` `sli` on((`sli`.`id_imagen` = `si`.`id_imagen`))
  )
  join `sat_indices_vegetacion` `siv` on((`siv`.`id_indice` = `sli`.`id_indice`))
  )
where
  (`siv`.`codigo` = 'NDVI')
order by
  `l`.`id_lote`,
  `si`.`fecha_captura` desc;

# ------------------------------------------------------------
# SCHEMA DUMP FOR TABLE: v_sat_resumen_finca
# ------------------------------------------------------------

CREATE OR REPLACE VIEW `v_sat_resumen_finca` AS
select
  `f`.`id_tenant` AS `id_tenant`,
  `f`.`id_finca` AS `id_finca`,
  `f`.`nombre` AS `nombre_finca`,
  cast(`si`.`fecha_captura` as date) AS `fecha_lectura`,
  `siv`.`codigo` AS `indice_medido`,
  count(`si`.`id_imagen`) AS `total_imagenes_procesadas`,
  round(avg(`sli`.`valor_promedio`), 4) AS `promedio_indice`
from
  (
  (
    (
    (
      (
      `fincas` `f`
      join `nucleos` `n` on((`n`.`id_finca` = `f`.`id_finca`))
      )
      join `lotes` `l` on((`l`.`id_nucleo` = `n`.`id_nucleo`))
    )
    join `sat_imagenes` `si` on((`si`.`id_lote` = `l`.`id_lote`))
    )
    join `sat_lecturas_indices` `sli` on((`sli`.`id_imagen` = `si`.`id_imagen`))
  )
  join `sat_indices_vegetacion` `siv` on((`siv`.`id_indice` = `sli`.`id_indice`))
  )
group by
  `f`.`id_tenant`,
  `f`.`id_finca`,
  `f`.`nombre`,
  cast(`si`.`fecha_captura` as date),
  `siv`.`codigo`;

# ------------------------------------------------------------
# SCHEMA DUMP FOR TABLE: vw_estado_cuenta
# ------------------------------------------------------------

CREATE OR REPLACE VIEW `vw_estado_cuenta` AS
select
  `dc`.`id_tenant` AS `id_tenant`,
  `dc`.`id_tercero` AS `id_tercero`,
  'Factura Venta' AS `tipo_operacion`,
  `dc`.`numero_documento` AS `referencia`,
  `dc`.`fecha_emision` AS `fecha`,
  `dc`.`total` AS `cargo`,
  0.00 AS `abono`,
  `cxc`.`estado` AS `estado`,
  'CxC' AS `tipo_cartera`
from
  (
  `documentos_comerciales` `dc`
  join `cartera_cxc` `cxc` on((`dc`.`id_documento` = `cxc`.`id_documento`))
  )
union all
select
  `dc`.`id_tenant` AS `id_tenant`,
  `dc`.`id_tercero` AS `id_tercero`,
  'Pago Recibido' AS `tipo_operacion`,
  `a`.`referencia` AS `referencia`,
  `a`.`fecha_abono` AS `fecha`,
  0.00 AS `cargo`,
  `a`.`valor_abono` AS `abono`,
  'Pagado' AS `estado`,
  'CxC' AS `tipo_cartera`
from
  (
  (
    `abonos_cxc` `a`
    join `cartera_cxc` `cxc` on((`a`.`id_cxc` = `cxc`.`id_cxc`))
  )
  join `documentos_comerciales` `dc` on((`cxc`.`id_documento` = `dc`.`id_documento`))
  )
union all
select
  `dc`.`id_tenant` AS `id_tenant`,
  `dc`.`id_tercero` AS `id_tercero`,
  'Factura Compra' AS `tipo_operacion`,
  `dc`.`numero_documento` AS `referencia`,
  `dc`.`fecha_emision` AS `fecha`,
  `dc`.`total` AS `cargo`,
  0.00 AS `abono`,
  `cxp`.`estado` AS `estado`,
  'CxP' AS `tipo_cartera`
from
  (
  `documentos_comerciales` `dc`
  join `cartera_cxp` `cxp` on((`dc`.`id_documento` = `cxp`.`id_documento`))
  )
union all
select
  `dc`.`id_tenant` AS `id_tenant`,
  `dc`.`id_tercero` AS `id_tercero`,
  'Pago Emitido' AS `tipo_operacion`,
  `a`.`forma_pago` AS `referencia`,
  `a`.`fecha_abono` AS `fecha`,
  0.00 AS `cargo`,
  `a`.`valor_abono` AS `abono`,
  'Pagado' AS `estado`,
  'CxP' AS `tipo_cartera`
from
  (
  (
    `fin_abonos_cxp` `a`
    join `cartera_cxp` `cxp` on((`a`.`id_cxp` = `cxp`.`id_cxp`))
  )
  join `documentos_comerciales` `dc` on((`cxp`.`id_documento` = `dc`.`id_documento`))
  );

